// Dumps the compiled Jison parser that Mermaid 12.3 uses for a diagram type:
// LALR tables, productions, symbols, and the lexer rules and actions (the
// rules and actions are ported by hand; the tables are generated by gen.py).
// usage: node tools/jison/dump.js "<sample source>" out.json   (from tools/conformance)
const { chromium } = require('playwright'); const fs = require('fs'); const path = require('path');
(async () => {
  const [src, out] = process.argv.slice(2);
  const b = await chromium.launch(); const p = await b.newPage();
  await p.setContent('<html><body></body></html>');
  await p.addScriptTag({ path: path.resolve('node_modules/mermaid/dist/mermaid.min.js') });
  const r = await p.evaluate(async (src) => {
    mermaid.initialize({ startOnLoad: false });
    const d = await mermaid.mermaidAPI.getDiagramFromText(src);
    const P = d.parser.parser || d.parser;
    const L = P.lexer;
    return {
      table: P.table, productions: P.productions_, defaultActions: P.defaultActions,
      symbols: P.symbols_, terminals: P.terminals_, performAction: P.performAction.toString(),
      rules: L.rules.map((r) => r.source), conditions: L.conditions, lexAction: L.performAction.toString(),
    };
  }, src);
  fs.writeFileSync(out, JSON.stringify(r));
  await b.close();
})();
